import React from 'react';
import {
  Box,
  Typography,
  Link,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Chip,
  Divider,
  Grid
} from '@mui/material';
import {
  OpenInNew as OpenInNewIcon,
  Article as ArticleIcon,
  Language as LanguageIcon,
  Description as DescriptionIcon
} from '@mui/icons-material';
import ReactMarkdown from 'react-markdown';

const AgentResultDisplay = ({ data }) => {
  if (!data) return null;

  // Helper for Section Headers
  const SectionHeader = ({ icon, title, count }) => (
    <Box sx={{
      display: 'flex',
      alignItems: 'center',
      gap: 1.5,
      mb: 2,
      pb: 1,
      borderBottom: '2px solid #EFF6FF'
    }}>
      <Box sx={{
        p: 1,
        borderRadius: '8px',
        bgcolor: '#EFF6FF',
        color: '#2563EB',
        display: 'flex'
      }}>
        {icon}
      </Box>
      <Typography variant="h6" sx={{ fontWeight: 600, color: '#1E40AF' }}>
        {title}
      </Typography>
      {count !== undefined && (
        <Chip
          label={count}
          size="small"
          sx={{
            bgcolor: '#EFF6FF',
            color: '#2563EB',
            fontWeight: 600,
            height: 24
          }}
        />
      )}
    </Box>
  );

  // If data is a string, treat it as markdown
  if (typeof data === 'string') {
    return (
      <Box className="markdown-content" sx={{ p: 1 }}>
        <ReactMarkdown>{data}</ReactMarkdown>
      </Box>
    );
  }

  // If data has an 'analysis' field, use that as primary content
  if (data.analysis) {
    return (
      <Box className="markdown-content" sx={{ p: 1 }}>
        <ReactMarkdown>{data.analysis}</ReactMarkdown>

        {/* Render other structured data below analysis if present */}
        {Object.entries(data).map(([key, value]) => {
          if (key === 'analysis' || typeof value !== 'object' || value === null) return null;
          // Render tables/lists for other complex fields
          return (
            <Box key={key} sx={{ mt: 3 }}>
              <Typography variant="subtitle1" sx={{ fontWeight: 600, mb: 1, textTransform: 'capitalize' }}>
                {key.replace(/_/g, ' ')}
              </Typography>
              <Box component="pre" sx={{
                bgcolor: '#F8FAFC',
                p: 2,
                borderRadius: 2,
                overflow: 'auto',
                fontSize: '0.85rem',
                border: '1px solid #E2E8F0'
              }}>
                {JSON.stringify(value, null, 2)}
              </Box>
            </Box>
          );
        })}
      </Box>
    );
  }

  // Format structured data
  return (
    <Box>
      {/* Summary Section */}
      {data.summary && (
        <Box sx={{ mb: 4 }}>
          <SectionHeader icon={<DescriptionIcon />} title="Summary Analysis" />
          <Box className="markdown-content" sx={{
            bgcolor: '#F8FAFC',
            p: 3,
            borderRadius: 3,
            border: '1px solid #E2E8F0'
          }}>
            <ReactMarkdown>{data.summary}</ReactMarkdown>
          </Box>
        </Box>
      )}

      {/* PubMed Papers Table */}
      {data.pubmed_papers && Array.isArray(data.pubmed_papers) && data.pubmed_papers.length > 0 && (
        <Box sx={{ mb: 4 }}>
          <SectionHeader
            icon={<ArticleIcon />}
            title="Scientific Literature"
            count={data.pubmed_papers.length}
          />

          <TableContainer component={Paper} elevation={0} sx={{
            border: '1px solid #E2E8F0',
            borderRadius: 3,
            overflow: 'hidden'
          }}>
            <Table size="medium">
              <TableHead>
                <TableRow sx={{ bgcolor: '#F8FAFC' }}>
                  <TableCell sx={{ fontWeight: 600, color: '#475569' }}>Title</TableCell>
                  <TableCell sx={{ fontWeight: 600, color: '#475569' }}>Authors</TableCell>
                  <TableCell sx={{ fontWeight: 600, color: '#475569' }}>Source</TableCell>
                  <TableCell sx={{ fontWeight: 600, color: '#475569' }}>Year</TableCell>
                  <TableCell sx={{ fontWeight: 600, color: '#475569' }}>Action</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {data.pubmed_papers.map((paper, index) => (
                  <TableRow key={index} hover sx={{ '&:last-child td, &:last-child th': { border: 0 } }}>
                    <TableCell sx={{ fontWeight: 500, color: '#1E293B' }}>
                      {paper.title || 'N/A'}
                    </TableCell>
                    <TableCell sx={{ color: '#64748B' }}>
                      {paper.authors && Array.isArray(paper.authors)
                        ? paper.authors.slice(0, 2).join(', ') + (paper.authors.length > 2 ? ' et al.' : '')
                        : 'N/A'}
                    </TableCell>
                    <TableCell sx={{ color: '#64748B' }}>{paper.source || 'N/A'}</TableCell>
                    <TableCell sx={{ color: '#64748B' }}>{paper.pubdate || 'N/A'}</TableCell>
                    <TableCell>
                      {paper.url ? (
                        <Link
                          href={paper.url}
                          target="_blank"
                          rel="noopener noreferrer"
                          sx={{
                            display: 'inline-flex',
                            alignItems: 'center',
                            gap: 0.5,
                            color: '#2563EB',
                            textDecoration: 'none',
                            fontWeight: 500,
                            '&:hover': { textDecoration: 'underline' }
                          }}
                        >
                          View <OpenInNewIcon sx={{ fontSize: 16 }} />
                        </Link>
                      ) : 'N/A'}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </Box>
      )}

      {/* Web Sources Cards */}
      {data.web_sources && Array.isArray(data.web_sources) && data.web_sources.length > 0 && (
        <Box sx={{ mb: 4 }}>
          <SectionHeader
            icon={<LanguageIcon />}
            title="Web Intelligence"
            count={data.web_sources.length}
          />

          <Grid container spacing={2}>
            {data.web_sources.map((source, index) => (
              <Grid item xs={12} md={6} key={index}>
                <Paper
                  elevation={0}
                  sx={{
                    p: 2.5,
                    height: '100%',
                    border: '1px solid #E2E8F0',
                    borderRadius: 3,
                    transition: 'all 0.2s',
                    '&:hover': {
                      borderColor: '#2563EB',
                      boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)'
                    }
                  }}
                >
                  <Typography variant="subtitle1" sx={{ fontWeight: 600, mb: 1, lineHeight: 1.3 }}>
                    {source.title || 'Untitled Source'}
                  </Typography>

                  {source.snippet && (
                    <Typography variant="body2" sx={{ color: '#64748B', mb: 2, display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical', overflow: 'hidden' }}>
                      {source.snippet}
                    </Typography>
                  )}

                  <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mt: 'auto' }}>
                    {source.source && (
                      <Chip
                        label={source.source}
                        size="small"
                        sx={{ bgcolor: '#F1F5F9', color: '#475569', fontWeight: 500 }}
                      />
                    )}
                    {source.url && (
                      <Link
                        href={source.url}
                        target="_blank"
                        rel="noopener noreferrer"
                        sx={{
                          display: 'inline-flex',
                          alignItems: 'center',
                          gap: 0.5,
                          fontSize: '0.875rem',
                          color: '#2563EB',
                          textDecoration: 'none',
                          fontWeight: 500
                        }}
                      >
                        Visit <OpenInNewIcon sx={{ fontSize: 14 }} />
                      </Link>
                    )}
                  </Box>
                </Paper>
              </Grid>
            ))}
          </Grid>
        </Box>
      )}

      {/* Key Statistics / Metadata */}
      {(data.total_sources || data.key_papers || data.analysis_type) && (
        <Box sx={{
          p: 2,
          bgcolor: '#F8FAFC',
          borderRadius: 2,
          border: '1px solid #E2E8F0',
          display: 'flex',
          gap: 3,
          flexWrap: 'wrap'
        }}>
          {data.total_sources && (
            <Box>
              <Typography variant="caption" sx={{ color: '#64748B', display: 'block' }}>Total Sources</Typography>
              <Typography variant="subtitle2" sx={{ fontWeight: 600 }}>{data.total_sources}</Typography>
            </Box>
          )}
          {data.key_papers && (
            <Box>
              <Typography variant="caption" sx={{ color: '#64748B', display: 'block' }}>Key Papers</Typography>
              <Typography variant="subtitle2" sx={{ fontWeight: 600 }}>{data.key_papers}</Typography>
            </Box>
          )}
          {data.analysis_type && (
            <Box>
              <Typography variant="caption" sx={{ color: '#64748B', display: 'block' }}>Analysis Type</Typography>
              <Chip
                label={data.analysis_type}
                size="small"
                sx={{ height: 20, fontSize: '0.75rem', bgcolor: '#DBEAFE', color: '#1E40AF' }}
              />
            </Box>
          )}
        </Box>
      )}
    </Box>
  );
};

export default AgentResultDisplay;
